<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trip Controls · {{ $company?->name }}</title><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>
*{box-sizing:border-box}body{margin:0;background:#f3f6fb;color:#172033;font-family:Arial,sans-serif}.shell{max-width:620px;margin:auto;padding:18px}.brand{display:flex;align-items:center;gap:12px;margin:8px 0 20px}.brand img{max-width:54px;max-height:54px}.brand strong{font-size:22px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:20px;margin-bottom:14px;box-shadow:0 8px 30px rgba(15,23,42,.05)}.label{color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:.8px}.status{display:inline-block;margin-top:8px;padding:6px 10px;border-radius:20px;background:#e2e8f0;font-weight:700;text-transform:capitalize}.route{margin:12px 0;padding:10px 0;border-bottom:1px solid #eef2f7}.route:last-child{border:0}.route small{display:block;color:#64748b;margin-bottom:4px}button{width:100%;border:0;border-radius:10px;padding:15px;background:#0f172a;color:#fff;font-size:16px;font-weight:700;cursor:pointer}button:disabled{opacity:.45}.notice{padding:12px;border-radius:9px;background:#eef6ff;color:#1e40af;margin-bottom:12px;font-size:14px}.error{background:#fff1f2;color:#be123c}.vehicle{color:#475569;line-height:1.6}#driverMap{height:310px;border-radius:10px;background:#e2e8f0;margin-top:12px}.sharing{display:flex;align-items:center;gap:8px;font-weight:700;margin-top:14px}.sharing-dot{width:11px;height:11px;border-radius:50%;background:#94a3b8}.sharing.active{color:#15803d}.sharing.active .sharing-dot{background:#22c55e;box-shadow:0 0 0 4px #dcfce7}.sharing.stopped{color:#be123c}.sharing.stopped .sharing-dot{background:#e11d48}.driver-warning{margin:12px 0 0;padding:12px;border-left:4px solid #f59e0b;background:#fffbeb;color:#92400e;font-size:14px;line-height:1.5}.timer{margin:10px 0;color:#64748b;font-size:14px;font-variant-numeric:tabular-nums}
</style></head><body><main class="shell"><div class="brand">
