@endif
<strong>{{ $company?->name ?? config('app.name') }}</strong></div><div id="notice" class="notice">Loading trip…</div><section class="card"><div class="label">Booking</div><h1 style="margin:5px 0 8px;font-size:25px;">#{{ $booking->id }}</h1><div id="status" class="status">{{ str_replace('_',' ',$booking->status) }}</div></section><section class="card"><div class="label">Route</div><div class="route"><small>Pickup</small><strong>{{ $booking->pickup_address }}</strong></div>
<div id="driverStops">@foreach($booking->stops as $stop)
<div class="route"><small>Stop {{ $stop->position }}</small><strong>{{ $stop->address }}</strong></div>
@endforeach</div>
@if($booking->dropoff_address)
<div class="route"><small>Drop-off</small><strong>{{ $booking->dropoff_address }}</strong></div>
@endif
</section>
<section class="card"><div class="label">Passenger</div><div class="route"><small>Name</small><strong>{{ $booking->name ?: $booking->customer?->name ?: 'Not provided' }}</strong></div></section><section class="card"><div class="label">Trip schedule</div>@if($booking->pickup_time)<div class="route"><small>Pickup date &amp; time</small><strong>{{ \Carbon\Carbon::parse($booking->pickup_time)->format('D, d M Y \a\t h:i A') }}</strong></div>@endif @if($booking->dropoff_time)<div class="route"><small>Expected drop-off</small><strong>{{ \Carbon\Carbon::parse($booking->dropoff_time)->format('D, d M Y \a\t h:i A') }}</strong></div>@endif</section>
<section id="dispatchCard" class="card" hidden><div class="label">Trip Dispatch</div><p style="line-height:1.5;color:#475569;">Please confirm whether you can take this trip.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;"><button id="acceptDispatchBtn" type="button">Accept</button><button id="rejectDispatchBtn" type="button" style="background:#b91c1c;">Reject</button></div></section>
