<section class="card vehicle"><div class="label">Vehicle</div><strong>{{ $booking->vehicle->name }}</strong><br>{{ collect([$booking->vehicle->color,$booking->vehicle->model,$booking->vehicle->plate_number])->filter()->join(' · ') }}</section>
@endif
<section class="card"><div class="label">Your live location</div><div id="driverMap"></div><div id="sharingIndicator" class="sharing"><span class="sharing-dot"></span><span id="sharingText">Location sharing not started</span></div><p class="driver-warning"><strong>Important:</strong> Keep this page open and your phone unlocked during the trip for continuous live-location updates.</p></section>
<section class="card"><button id="statusBtn" disabled>Loading…</button></section><section class="card"><div class="label">Trip stop timer</div><div id="pauseTimer" class="timer">No stop time recorded</div><button id="pauseBtn" type="button" disabled>Stop</button></section></main><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
const token=@json($token),api='/api/public/driver-trips/'+encodeURIComponent(token),notice=document.getElementById('notice'),button=document.getElementById('statusBtn'),statusEl=document.getElementById('status'),sharingIndicator=document.getElementById('sharingIndicator'),sharingText=document.getElementById('sharingText'),pauseButton=document.getElementById('pauseBtn'),pauseTimer=document.getElementById('pauseTimer'),dispatchCard=document.getElementById('dispatchCard'),acceptDispatchButton=document.getElementById('acceptDispatchBtn'),rejectDispatchButton=document.getElementById('rejectDispatchBtn');let trip=null,watchId=null,map=null,marker=null,wakeLock=null,wakeLockRequesting=false,pauseInterval=null;const labels={on_route:'Start Trip',on_location:'Arrived at Pickup',pob:'Passenger On Board',done:'Complete Trip'};
async function call(url,options={}){const response=await fetch(url,{headers:{'Accept':'application/json','Content-Type':'application/json'},...options});const payload=await response.json();if(!response.ok)throw new Error(payload.message||'Request failed');return payload}
async function acquireWakeLock(){if(!('wakeLock' in navigator)||document.visibilityState!=='visible'||wakeLock!==null||wakeLockRequesting||trip?.status==='done')return;wakeLockRequesting=true;try{const lock=await navigator.wakeLock.request('screen');wakeLock=lock;lock.addEventListener('release',()=>{if(wakeLock===lock)wakeLock=null})}catch(error){wakeLock=null}finally{wakeLockRequesting=false}}
async function releaseWakeLock(){const lock=wakeLock;wakeLock=null;if(lock&&!lock.released){try{await lock.release()}catch(error){}}}
function setSharing(state,text){sharingIndicator.className='sharing '+state;sharingText.textContent=text}
function showPosition(position){const point=[position.coords.latitude,position.coords.longitude];if(!map){map=L.map('driverMap').setView(point,16);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);marker=L.marker(point).addTo(map)}else{marker.setLatLng(point);map.panTo(point)}}
function formatElapsed(seconds){const hours=Math.floor(seconds/3600),minutes=Math.floor((seconds%3600)/60),remaining=seconds%60;return (hours?String(hours).padStart(2,'0')+':':'')+String(minutes).padStart(2,'0')+':'+String(remaining).padStart(2,'0')}
function updatePauseTimer(){if(!trip)return;const recorded=(trip.pause_minutes||0)*60;if(trip.pause_active&&trip.pause_started_at){const started=new Date(trip.pause_started_at).getTime();pauseTimer.textContent='Stop time: '+formatElapsed(recorded+Math.max(0,Math.floor((Date.now()-started)/1000)))}else pauseTimer.textContent=recorded?'Recorded stop time: '+formatElapsed(recorded):'No stop time recorded'}
function render(data){trip=data;statusEl.textContent=String(data.status).replaceAll('_',' ');dispatchCard.hidden=data.status!=='dispatched';button.textContent=data.next_status?labels[data.next_status]:'Trip controls completed';button.disabled=!data.next_status;const canPause=['on_route','on_location','pob'].includes(data.status);pauseButton.disabled=!canPause;pauseButton.textContent=data.pause_active?'Resume':'Stop';if(pauseInterval)clearInterval(pauseInterval);updatePauseTimer();if(data.pause_active)pauseInterval=setInterval(updatePauseTimer,1000);if(data.status!=='done'&&data.status!=='dispatched')acquireWakeLock();if(['on_route','on_location','pob'].includes(data.status))startLocation();else if(data.status==='assigned')setSharing('','Location sharing starts when the trip starts');else if(data.status==='dispatched')setSharing('','Accept this trip to enable location sharing');if(data.status==='done'){notice.textContent='Trip completed. Location sharing has stopped.';stopLocation();releaseWakeLock()}}
async function load(){try{const data=(await call(api)).data;render(data);if(data.status!=='done')notice.textContent='Allow location access to share your position during the trip.'}catch(error){releaseWakeLock();notice.classList.add('error');notice.textContent=error.message}}
button.addEventListener('click',async()=>{acquireWakeLock();if(!trip?.next_status)return;button.disabled=true;try{render((await call(api+'/status',{method:'POST',body:JSON.stringify({status:trip.next_status})})).data)}catch(error){notice.classList.add('error');notice.textContent=error.message;button.disabled=false}});
pauseButton.addEventListener('click',async()=>{if(!trip||pauseButton.disabled)return;pauseButton.disabled=true;try{const response=await call(api+'/pause',{method:'POST'});render(response.data);notice.classList.remove('error');notice.textContent=response.message}catch(error){notice.classList.add('error');notice.textContent=error.message;render(trip)}});
async function respondToDispatch(response){if(!trip||trip.status!=='dispatched')return;acceptDispatchButton.disabled=true;rejectDispatchButton.disabled=true;try{const result=await call(api+'/dispatch-response',{method:'POST',body:JSON.stringify({response})});render(result.data);notice.classList.remove('error');notice.textContent=result.message}catch(error){notice.classList.add('error');notice.textContent=error.message;acceptDispatchButton.disabled=false;rejectDispatchButton.disabled=false}}
acceptDispatchButton.addEventListener('click',()=>respondToDispatch('accepted'));rejectDispatchButton.addEventListener('click',()=>respondToDispatch('rejected'));
function startLocation(){if(watchId!==null)return;if(!navigator.geolocation){setSharing('stopped','Location sharing is not supported by this browser');return}setSharing('','Waiting for location permission…');watchId=navigator.geolocation.watchPosition(async position=>{showPosition(position);try{await call(api+'/location',{method:'POST',body:JSON.stringify({latitude:position.coords.latitude,longitude:position.coords.longitude,accuracy:position.coords.accuracy,heading:position.coords.heading,speed:position.coords.speed,recorded_at:new Date(position.timestamp).toISOString()})});notice.classList.remove('error');notice.textContent='Location sent · '+new Date().toLocaleTimeString();setSharing('active','Location sharing active')}catch(error){notice.classList.add('error');notice.textContent=error.message;setSharing('stopped','Location sharing stopped')}},error=>{notice.classList.add('error');notice.textContent='Location permission is required: '+error.message;setSharing('stopped','Location sharing stopped — check permission')},{enableHighAccuracy:true,maximumAge:5000,timeout:15000})}
function stopLocation(){if(watchId!==null)navigator.geolocation.clearWatch(watchId);watchId=null;setSharing('stopped','Location sharing stopped')}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&watchId!==null)setSharing('stopped','Location sharing may be paused while the page is hidden');if(!document.hidden){if(trip?.status!=='done')acquireWakeLock();if(trip&&['on_route','on_location','pob'].includes(trip.status))setSharing('','Checking location sharing…')}});window.addEventListener('pagehide',releaseWakeLock);acquireWakeLock();load();
</script></body></html>
